cards=[]
cards.append(compact('ban_deng','班登','班登兼具医学与遗传学背景，又以东方历史研究者的名片接近卫斯理，关心太平天国人物画像的缺席。他惯于先绕着真正目的说话，利用对方的好奇心推动调查，因此也不断损耗合作中的信任。《密码》留下了他找到改变遗传密码的材料、声称培育怪物并送交勒曼医院研究的印象，后来《解开密码》的调查却把这个说法修正：怪蛹本来就是从藏宝线索中找到的，不能继续把创造该生命的能力记在班登名下。他希望从样本找到远超当代的生物知识，既有科研欲望，也曾隐瞒关键事实；当医院独占样本、先拒绝归还再宣称销毁时，他又转而担忧研究会给人类带来危险，求助非人协会。随后返回发现地点，找到容器的盖子，使后来的争夺和解码成为可能。终局卡保留他的专业、怀疑与研究执念，不给他已经失去的怪蛹，也不把对历史记载的推断当作对古人基因的绝对知识。他需要学会把不利于自己的证据也交给合作者，否则聪明的迂回会再次让合作破裂。','《解开密码》经非人协会追索样本、找到容器盖；怪蛹与主体容器不在其个人控制之下','主角','寻找生命形成的秘密，并在机构失去透明度时争取研究控制权','善用中国历史和语言引起对方兴趣，谈论科研时格外急切','重要样本被扣留时转向其他组织求援，必要时承认原先隐瞒','研究价值不能代替证据来源；发现与创造必须分清',[ab('医学与遗传研究','以医学、遗传学及历史资料交叉解释异常样本','未证实独立创造怪蛹；复杂技术仍依赖研究机构'),ab('历史线索追寻','追查藏宝资料并返回原地点搜寻相关物件','不会自动知道所有古代遗物用途，也不能保证合作机构守信')],[ev('073',252,270,'研究员名片与迂回接近'),ev('073',3651,3709,'遗传学兴趣及早期说法'),ev('132',1028,1088,'后作修正发现来源、医院扣留和求助协会')],profile='expert'))
cards.append(compact('wen_boru','温伯如','温伯如是温宝裕的父亲，温家祖传药业的主人，把日常经营交给精明的妻子，自己常年沉在书籍、药物和梦的研究中。他的本名在早作中作温大富，伯如是自取的号，倒读有比拟刘伯温的意味；这个看似被妻子和儿子遮住的男人，其实对自己的见识有强烈自信。他不随便要求儿子办事，一旦有事却希望卫斯理亲自登门，又不能忍受来客轻视自己的成果。黑甜汤使他体验到另一种人生，温宝裕和红绫服药后也进入相同场景与他相会，说明不能只当作普通个人梦境打发。不过把这些经历解释成脑活动、异时空或神的法则，仍是众人的理论，并没有证明他已经掌握任意穿越。他能以愿望结束体验，对梦中生活又极为留恋；所用药物当前只通向固定的时间和地点。他宁可把药收回，也不愿以奇迹商品的身份让不信者随意消费。终局的互动应表现隐居研究者的自负、认真与父亲不善言表的温情，而不是把一家药店背后的安静长者改写为能任意安排所有人命运的神。','《异种人生》保留黑甜汤和入梦研究，当前固定体验地点；未来扩展属于未实现设想','主角','保护自己珍视的研究成果与梦中生活，得到真诚理解','慢条斯理谈药理和古书，不愿按世俗商业标准证明自己','被轻视时收回分享；需要结束体验时依主观愿望返回','亲身经历是真实体验，理论解释仍可有空白，不把未实现设想当现成法术',[ab('黑甜汤','以药物使服用者进入可共同会合的特殊体验，另有气味强烈的唤醒药物','当前只对应固定时间地点；不是随意改写历史或瞬移肉体'),ab('传统药学研究','结合祖传药业知识和长期实验配制助眠相关药物','不代表能诊治一切疾病，也未转交勒曼医院证实全部机制')],[ev('133',17,32,'父亲身份、自号与家庭性情'),ev('133',121,125,'喷剂唤醒'),ev('133',615,650,'共同体验、固定边界和收药结局')],profile='expert',aliases=['温大富','伯如'],extra={'uncertainties':['《异种人生》有乱码缺损，只采可读段落。','共享体验的物理本质未获独立证明，不能据人物推论扩大能力。']}))
