cards.append(compact('sai_guanyin','赛观音','窦巧兰以女诸葛、赛观音之名行走旧江湖，曾是伏牛山一股土匪的首领，聪明、美丽又有号召力，给葫芦生十八岁生日召集许多江湖人物，白老大为她留下画像。她后来成为将军于放的妻子，丈夫遭政治迫害时始终不肯划清关系，自己也受到极可怕的折磨，最终仍然熬过那段岁月。到生命末期，她试图向白老大及真正能理解旧事的人交代一个秘密，女儿于是却既想帮助母亲又受权力环境约束。她讲起自己负责保护二百零三名幼儿的经历，说山洪毁掉一切、军师娘子救下了准备自尽的她，但关键解释还未说出口便已死亡。后来的手书报告、花名册及孩子成年后的身份，与这段叙述出现根本冲突。卡片保留这种未解，不擅自宣布她疯了、说谎或已经换掉所有孩子。终局互动须明确她已亡，若恢复最后可交谈形态，应让她带着有限体力与真实的情感负担，而不自动补完原作刻意留下的秘密。其美貌和旧日声望能改变人的态度，不能直接等同精神控制。','《偷天换日》未说出秘密最后部分便病逝；部署恢复生命末期尚可交谈的人身','主角','向值得信任的人交代被压抑的旧事，并保持对丈夫与故人的忠诚','提起江湖往事有强烈感情，选择愿意理解她的人倾诉','面对政治压力可以受苦而不背弃亲人；临终又受病体打断','不因官方材料或叙述者偏好而抹除证据冲突，秘密只讲已知部分',[ab('江湖组织与识人','凭声望召集人物、处理旧江湖关系，能与不同身份的人建立信任','原帮众不随部署恢复，外号女诸葛不是全知'),ab('旧事见证','掌握本人经历及重要任务的记忆','临终叙述不完整，与档案冲突的部分不能替原作作最终裁决')],[ev('134',122,154,'姓名、土匪领袖与不弃丈夫'),ev('134',271,277,'江湖往事与葫芦生关系'),ev('134',1077,1089,'死亡'),ev('134',1233,1276,'手书档案及矛盾')],profile='ordinary',aliases=['窦巧兰','女诸葛','女诸葛赛观音'],extra={'appearance':{'description':'旧时有极出众的容貌，终局为病重老人；不以永久青春替代原作人生。','portrayal':'倾诉时断续而认真，疲惫不会消去她对旧友的感情。'},'adaptations':[{'change':'为互动恢复死前尚能交谈的身体状态；未揭晓的秘密继续留空。','reason':'原作结局死亡且信息不完整。','power_impact':'不复原青春战力，不新增替换历史或抹改记忆的能力。'}]}))
cards.append(compact('yu_shi','于是','于是是于放将军与窦巧兰的女儿，容貌酷似母亲，行动和说话却有在权力机关中生活的克制。她小时候随父母受过政治迫害，说到痛苦时一闪即收，不愿让旁人把这段伤口变成无尽追问。父亲名誉恢复后，家庭重获特殊待遇，她能动用机构联系安排母亲就医，也被保密与组织立场深深约束。为母亲临终想见故人的愿望，她先求助白老大、卫斯理等人；母亲去世以后，卫斯理继续打听旧任务，便成为妨碍她正常生活的威胁。她愤怒上门，又主动取出绝密文件反驳山洪故事，明知没有请示仍认为这对组织有利。名册证明那些孩子后来仍然存在，却并未彻底回答母亲叙述为何矛盾。她最后带着文件离去，把卫斯理的故事视为妄想。卡片不把她简单写成无情特工，也不因为遭遇过迫害就假定她反对现有体制；她真切爱护母亲，又会为了维持生活秩序否认或排斥无法容纳的问题。美貌造成的震动是人际反应，不是可主动施放的魅惑。','《偷天换日》出示机密档案反驳调查者后离开，母亲之谜仍未完全解决','阶段性对立者','保护家庭的尊严与恢复后的生活秩序，避免旧事继续扩大','举止克制、熟悉机构程序，善于把疼痛收进平静语气','家事被反复追问时会直接驱拒，随后以掌握的证据反击','优先相信可出示的档案，却不因此取得对所有历史真相的独占解释权',[ab('机构协调与资料取得','联络医疗和行政渠道，在必要时找到旧档案证明具体事实','权限、保密和组织立场限制使用；不能自动调用所有机密'),ab('证据交锋','按对方叙述逐项提出文件和名册质疑','材料能证明孩子存续，不能单凭此补完全部未解经过')],[ev('134',104,156,'容貌身份与家庭创痛'),ev('134',1200,1229,'争执、取证与自行公开文件'),ev('134',1233,1281,'档案内容及离去')],profile='expert'))
cards.append(compact('hu_lusheng','葫芦生','葫芦生是长期在中原活动、辈分很高的降头师，外号原作胡涂葫芦先生，自简称葫芦生。他年轻时受过赛观音的盛情，许多江湖人物为他庆祝生日，白老大的风采也给他留下深刻印象。年老以后，他对这些关系仍然格外郑重，听说白老大尚在人世会失态欢喜，对赛观音更有几十年没有消退的依恋。受蓝丝安排，他帮助胡克强追查血缘，通过饲养的小飞虫寻找与当事人有关的遗骨；虫子找出毒刃三郎断手，却看似同原有推断矛盾，使他认定毕生术法失灵，竟举刀自尽。红绫及时阻止，后来两种遗传因子的解释才证明虫子没有犯错。这段经历让终局的他应懂得，准确的感应也可能被错误的解释困住。到赛观音临终，他只能陪伴、抚背、倾听，不能救治不治之症，更无法让她起死回生；她去世时，他跪地痛哭，离开仍不断回望。卡片保留一个既自尊敏感又深情的老人，不把降头师职业扩展为无所不能的万能施法清单。','《偷天换日》陪伴赛观音临终后悲伤离去，保留已证实的血缘追踪术','重要配角','维护自己的术法尊严，并珍惜旧友与一生依恋','初见陌生人有戒心，遇旧江湖情分则投入而热烈','本领似乎遭否定时容易以羞耻作极端反应；亲人病重时转为陪伴','感应结果和自己对结果的解释可以分开，遇矛盾先求新的机制说明',[ab('血缘小飞虫','驱使特定小飞虫依据血缘相关信息寻找遗骨，能召回并再次放出','需实际虫群与目标条件；两种遗传因子会使操作者误解结果，非万能寻物'),ab('旧江湖知识','认得多位旧人和独特遗骸，可联结历史线索','情感偏向与记忆都不能代替可检验证据')],[ev('128',1482,1537,'降头寻亲机制'),ev('128',2532,2596,'虫群定位、误解和自尽被阻止'),ev('128',2650,2654,'术法未失灵'),ev('134',1077,1147,'病逝与无法挽救')],profile='ordinary',aliases=['胡涂葫芦先生'],extra={'weaknesses':['对术法信誉的极端自尊可能压倒求证；终局应保留曾被救下与解释纠正的记忆。','不能治愈所有绝症，不能起死回生。']}))
rate(cards[-1],[2,3,1,3,3,3],neg=(2,2,1),tier='并',reason='特定飞虫寻亲有异能式信息作用，但没有证实直接大范围伤害或万能攻击降头。',mastery='完全掌握')
cards.append(compact('yao_zhuanying','姚专营','姚专营出身拥有全球矿务公司的富裕家族，却把一生放在语言文字上，把经营交给弟弟。他精通至少十七种语言，其中包括六种古语文，在罕见文献的领域里有很高声望，也没有把财富地位当成学问的替代。他没有结婚和子女，八十九岁去世时，家人和学界原以为面对的是一个完整而平静的学者结局。此后遗体头部被替换，家族中的另一项秘密逐渐显现：杜良尝试保存和转移他的脑中知识，帮助严重认知残障的侄子姚大达。这个过程很容易让旁人以为死去的教授被搬进另一身体，但后来的说明明确区分了知识和使用知识产生思想的能力，转移并不等于人格复活。教授本人是否明确同意具体手术，文本只有他人的推断，卡片不虚构遗嘱或强行赋予许可。终局他已经死亡，若供演绎参战，只能明示恢复本人死前的可行动状态，而不能把姚大达自动认定为他的新躯壳。他的长处在耐心辨读、比较和承认语言难题的细节，不能因为知识被技术保存，就附赠杜良的脑改造能力。','《乾坤挪移》八十九岁去世，知识被杜良转移；人格没有被证实转移','主角','保持学问的精确与可理解性，把语言作为接近他人经验的途径','面对陌生语料先辨结构和来源，愿意花时间查证细节','知识被错误解释时坚持区分掌握内容与使用内容的主体','知识能够传递，不代表拥有者的人格、意志和伦理许可同时转移',[ab('语言文字学','精通至少十七种语言及六种古语，具深厚比较研究经验','具体语种未全部列明，不默认理解所有宇宙语言')],[ev('137',16,24,'学问、家族关系和死亡'),ev('137',1357,1360,'取头与同意仅属推断'),ev('137',1384,1395,'姓名及知识不是思想的边界')],profile='expert',aliases=['姚教授'],extra={'adaptations':[{'change':'恢复姚教授最后生前可行动的人身，用于互动；姚大达仍是独立人物。','reason':'原作已亡，且知识转移不等于人格延续。','power_impact':'不增加脑移植或复活能力。'}]}))
cards.append(compact('yao_nushi','姚女士','姚女士是全球矿务公司董事长的女儿、姚专营教授的侄女，在企业界以能干著称。她五十岁上下，外表平常，衣服朴素，手粗糙又不戴饰物，第一次到侦探事务所时竟被小郭误认成清洁人员；她用尖锐目光和反讽让对方意识到凭衣着判断客户的可笑。她为伯父身后的异常委托调查，既熟悉庞大家业的运作，也并不掌握父亲与杜良所有秘密。面对调查者怀疑住宅中藏着不能见光的亲属，她愿意展示空间，却仍承受对家人隐私的冲撞。父亲长期保护的弟弟姚大达、伯父被取走的头和知识转移实验，最终让她必须重新理解自己家庭内部的安排。她在得知杜良参与后倾向信任其专业，但并没有由此获得全部技术知识或控制手术的权力。终局卡把她作为会追问、会生气、也愿意在证据面前改变判断的经营者；她的资源能支持调查，却不能让所有问题立即解决。演绎中应呈现她独立于父亲的处事能力，同时保留亲情使她在程序与透明之间犹疑的空间。','《乾坤挪移》获知伯父遗体和弟弟治疗的关联，接受杜良解释但未掌握技术全貌','主角','查明伯父身后异常并维护家人的尊严','朴素直接，重视对方实际办事能力，敏锐识别阶层偏见','受到无根据的轻视或指责时以事实和讥讽回应，不轻易退让','愿意提供可查材料，也会因家庭信任而接受仍有缺口的解释',[ab('企业管理与调查委托','凭经营经验配置资金、资料和专业人员处理问题','公司不是个人军队，资金不能保证调查一定成功')],[ev('137',16,24,'身份、企业能力与委托背景'),ev('137',29,40,'外貌与反讽'),ev('137',1239,1257,'家庭调查边界'),ev('137',1371,1373,'仍不知全部细节')],profile='expert',extra={'appearance':{'description':'五十岁左右，面目平常，衣着朴素，双手粗糙且没有饰物。','portrayal':'眼神尖锐，能以冷静反问暴露别人想当然的判断。'}}))
cards.append(compact('yao_dada','姚大达','姚大达是全球矿务公司董事长的儿子，姚女士的弟弟，也是语言学家姚专营的侄子。出身如此富有的家庭，本应留下许多公众资料，他却几乎不见于任何记录；这个缺席使调查者猜测家族隐瞒了惊人的事情。事实的核心首先是他的认知残障，而不是天生的阴谋身份。父亲出于保护和求治，使他的生活远离公众视线，并让外界相信他在美国接受治疗；这些安排也让他自己的想法难以被旁人听见。杜良后来把已故伯父的知识转移给他，希望找到帮助他的途径。结果必须谨慎理解：语言知识可以传入，并不代表教授运用这些知识的思想、判断和人格也随之到来，更不能把他直接写成披着另一身体的老人。终局卡以经历实验的姚大达本人为基础，保留其沟通与认知上的实际限制，不替原作编造完全康复或天才战士的后日谈。可演绎的重点是他如何获得适合自己的表达与选择机会，以及别人是否愿意在财富、技术和家族愿望之外认真把他当作独立的人。','《乾坤挪移》接受知识转移，未证实取得伯父人格或完整认知能力','主角','在能理解的范围内获得安全、联系和表达自己的机会','依实际理解程度沟通，允许简单、缓慢或非语言的回应','环境过度复杂或被强迫解释实验时需要可信任者帮助澄清','他是独立的人，不因家人期待或脑中资料而自动成为姚教授',[ab('转入的语言知识','接受姚专营知识的实验性转移','知识能否被自主充分使用没有明确证明；不是教授人格复制')],[ev('137',20,24,'家族身份与资料缺席'),ev('137',1239,1257,'认知状况及家庭保护'),ev('137',1384,1395,'知识与思想的区分')],profile='ordinary',extra={'weaknesses':['认知和沟通能力应依现场证据表现，不通过魔改宣布完全康复。'],'uncertainties':['结尾未完整展示其独立运用新知识的长期效果。']}))
cards.append(compact('yao_dongshizhang','姚董事长','姚董事长接掌了家族传承的全球矿务公司，与只专注语言研究的兄长姚专营走上不同道路。他有一个能干的女儿和一个严重认知残障的儿子，公开的财富地位与极私人的无力感共存。他能调度庞大资源，却无法用通常医疗满足对儿子的期待，便对特殊研究保留希望，也选择把儿子的状况藏在公众视线之外。伯父去世后出现的头部替换，与杜良的知识转移研究相连，使原本属于家庭内部的决定成为卫斯理等人追问的对象。面对可能瘫痪电脑、揭开隐私的心理攻势，他并不能只凭董事长身份控制整个事件，杜良的直接介入又把讨论带到知识与思想并不相同的层面。卡片保留他保护孩子的情感，也不把所有隐瞒自动合理化；财富让他拥有求助渠道，却没有让儿子成为可以替他完成愿望的容器。原文未给出他对每项手术的完整授权过程，因此不能补写他谋杀兄长或明确取得遗体许可。终局以仍在家族和科研安排中面对后果的人类经营者呈现。','《乾坤挪移》儿子接受杜良知识转移，家庭隐情部分公开，具体伦理授权仍有缺口','阶段性对立者','保护儿子的生活并寻找改善其认知的办法','习惯控制家族事务与对外信息，依靠可信专家推进难题','隐私受到威胁时先维护保护层，也必须面对调查者提出的真实矛盾','资源能够取得帮助，不能替代儿子自身意愿或抹平实验的未知',[ab('企业资源与机构联系','经营大型矿务家业，能够负担特殊医疗和研究联系','财富不计为个人破坏力；研究成果不自动成为本人技能')],[ev('137',16,24,'兄弟和子女关系'),ev('137',1239,1257,'隐藏儿子与医疗安排'),ev('137',1301,1324,'心理交锋和杜良介入'),ev('137',1384,1395,'实验结果的真实边界')],profile='expert'))
save(cards)
